mapper.select:
SELECT DISTINCT strategy_option_id, action_type FROM strategy_action WHERE is_deleted = 0 AND strategy_option_id IN
#{strategyOptionId}
ORDER BY strategy_option_id, action_type

SELECT DISTINCT scopes.final_selection_id, scopes.scope_type, scopes.scope_code, scopes.scope_name FROM ( SELECT selection.final_selection_id, 'WAREHOUSE' AS scope_type, source_warehouse.warehouse_code AS scope_code, source_warehouse.warehouse_name AS scope_name FROM final_strategy_selection selection JOIN strategy_action action ON action.strategy_option_id = selection.strategy_option_id AND action.is_deleted = 0 JOIN warehouse source_warehouse ON source_warehouse.warehouse_id = action.source_warehouse_id AND source_warehouse.active_yn = 'Y' AND source_warehouse.is_deleted = 0 WHERE selection.final_selection_id IN
#{finalSelectionId}
UNION ALL
SELECT selection.final_selection_id, 'WAREHOUSE', destination_warehouse.warehouse_code, destination_warehouse.warehouse_name FROM final_strategy_selection selection JOIN strategy_action action ON action.strategy_option_id = selection.strategy_option_id AND action.is_deleted = 0 JOIN warehouse destination_warehouse ON destination_warehouse.warehouse_id = action.destination_warehouse_id AND destination_warehouse.active_yn = 'Y' AND destination_warehouse.is_deleted = 0 WHERE selection.final_selection_id IN
#{finalSelectionId}
UNION ALL
SELECT selection.final_selection_id, 'WAREHOUSE', snapshot_warehouse.warehouse_code, snapshot_warehouse.warehouse_name FROM final_strategy_selection selection JOIN strategy_inventory_snapshot snapshot ON snapshot.strategy_case_id = selection.strategy_case_id AND snapshot.sales_point_id IS NULL AND snapshot.is_deleted = 0 JOIN warehouse snapshot_warehouse ON snapshot_warehouse.warehouse_id = snapshot.warehouse_id AND snapshot_warehouse.active_yn = 'Y' AND snapshot_warehouse.is_deleted = 0 WHERE selection.final_selection_id IN
#{finalSelectionId}
UNION ALL
SELECT selection.final_selection_id, CASE source_channel.channel_type WHEN 'OFFLINE' THEN 'OFFLINE_STORE' ELSE 'ONLINE_STORE' END, source_point.sales_point_code, source_point.sales_point_name FROM final_strategy_selection selection JOIN strategy_action action ON action.strategy_option_id = selection.strategy_option_id AND action.is_deleted = 0 JOIN sales_point source_point ON source_point.sales_point_id = action.source_sales_point_id AND source_point.active_yn = 'Y' AND source_point.is_deleted = 0 JOIN sales_channel source_channel ON source_channel.sales_channel_id = source_point.sales_channel_id AND source_channel.channel_type IN ('OFFLINE', 'ONLINE') AND source_channel.active_yn = 'Y' AND source_channel.is_deleted = 0 WHERE selection.final_selection_id IN
#{finalSelectionId}
UNION ALL
SELECT selection.final_selection_id, CASE target_channel.channel_type WHEN 'OFFLINE' THEN 'OFFLINE_STORE' ELSE 'ONLINE_STORE' END, target_point.sales_point_code, target_point.sales_point_name FROM final_strategy_selection selection JOIN strategy_action action ON action.strategy_option_id = selection.strategy_option_id AND action.is_deleted = 0 JOIN sales_point target_point ON target_point.sales_point_id = action.target_sales_point_id AND target_point.active_yn = 'Y' AND target_point.is_deleted = 0 JOIN sales_channel target_channel ON target_channel.sales_channel_id = target_point.sales_channel_id AND target_channel.channel_type IN ('OFFLINE', 'ONLINE') AND target_channel.active_yn = 'Y' AND target_channel.is_deleted = 0 WHERE selection.final_selection_id IN
#{finalSelectionId}
UNION ALL
SELECT selection.final_selection_id, CASE snapshot_channel.channel_type WHEN 'OFFLINE' THEN 'OFFLINE_STORE' ELSE 'ONLINE_STORE' END, snapshot_point.sales_point_code, snapshot_point.sales_point_name FROM final_strategy_selection selection JOIN strategy_inventory_snapshot snapshot ON snapshot.strategy_case_id = selection.strategy_case_id AND snapshot.sales_point_id IS NOT NULL AND snapshot.is_deleted = 0 JOIN sales_point snapshot_point ON snapshot_point.sales_point_id = snapshot.sales_point_id AND snapshot_point.active_yn = 'Y' AND snapshot_point.is_deleted = 0 JOIN sales_channel snapshot_channel ON snapshot_channel.sales_channel_id = snapshot_point.sales_channel_id AND snapshot_channel.channel_type IN ('OFFLINE', 'ONLINE') AND snapshot_channel.active_yn = 'Y' AND snapshot_channel.is_deleted = 0 WHERE selection.final_selection_id IN
#{finalSelectionId}
) scopes ORDER BY scopes.final_selection_id, scopes.scope_type, scopes.scope_code
